  {
    id: 4,
    item: 'Mechanical keyboard',
    quantity: 8,
    unitPrice: 95,
    discount: 5,
    total: '=ROUND(quantity * unitPrice * (1 - discount / 100), 2)',
  },
  {
    id: 5,
    item: 'Wireless mouse',
    quantity: 8,
    unitPrice: 45,
    discount: 5,
    total: '=ROUND(quantity * unitPrice * (1 - discount / 100), 2)',
  },
  {
    id: 6,
    item: 'Thunderbolt cable',
    quantity: 12,
    unitPrice: 29,
    total: '=ROUND(quantity * unitPrice * (1 - discount / 100), 2)',
  },
  {
    id: 7,
    item: 'On-site setup (hours)',
    quantity: 6,
    unitPrice: 120,
    total: '=ROUND(quantity * unitPrice * (1 - discount / 100), 2)',
  },
  {
    id: 8,
    item: 'Extended warranty',
    quantity: 4,
    unitPrice: 210,
    discount: 15,
    total: '=ROUND(quantity * unitPrice * (1 - discount / 100), 2)',
  },
];

const bottomPinnedRows: GridRowsProp = [
  {
    id: 9,
    item: 'Subtotal',
    total: '=SUM(COLUMN_VALUES("total"))',
  },
  {
    id: 10,
    item: 'Sales tax (8.25%)',
    total: '=ROUND(REF(COLUMN("total"), ROW(9)) * 0.0825, 2)',
  },
  {
    id: 11,
    item: 'Total due',
    total: '=REF(COLUMN("total"), ROW(9)) + REF(COLUMN("total"), ROW(10))',
  },
];

export default function FormulaBasic() {
  return (
    <div style={{ height: 400, width: '100%' }}>
      <DataGridPremium
        featureDependencies={{ formula: formulaFeature }}
        rows={rows}
        columns={columns}
        formulaA1Notation
        rowSelection={false}
        density="compact"
        showCellVerticalBorder
        showColumnVerticalBorder
        disablePivoting
        pinnedRows={{
          bottom: bottomPinnedRows,
        }}
      />
    </div>
  );
}

